contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        uint256 dep = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint256 balAfter = address(c).balance;

        assert(balAfter >= balBefore || dep == 0);
    }

    receive() external payable {}
}

